/**
 * AMD build for local_sectionmarker/sectionmarker.
 * v1.0.2 – marks individual course modules (id="module-{cmid}"), not sections.
 *
 * @module     local_sectionmarker/sectionmarker
 * @copyright  2025 Your Name <you@example.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(
    'local_sectionmarker/sectionmarker',
    ['core/ajax', 'core/notification', 'core/str'],
    function(Ajax, Notification, Str) {
        'use strict';

        var MARKER_CLASSES = ['sectionmarker-info', 'sectionmarker-achtung', 'sectionmarker-ok'];

        var MARKERS = {
            info:    {cssClass: 'sectionmarker-info'},
            achtung: {cssClass: 'sectionmarker-achtung'},
            ok:      {cssClass: 'sectionmarker-ok'}
        };

        var INJECTED_ATTR = 'data-sectionmarker-injected';

        // -----------------------------------------------------------------------
        // Apply / remove CSS class on the module element itself
        // -----------------------------------------------------------------------

        /**
         * Find <li id="module-{cmId}" class="activity ..."> by cmid.
         * Moodle sets data-id to the cmid on the activity <li>.
         *
         * @param  {string|number} cmId
         * @return {Element|null}
         */
        var findModuleElement = function(cmId) {
            var id = String(cmId);
            return (
                document.querySelector('#module-' + id) ||
                document.querySelector('li.activity[data-id="' + id + '"]') ||
                document.querySelector('.activity[data-id="' + id + '"]')
            );
        };

        // -------------------------------------------------------------------
        // Ownership
        //
        // A subsection is itself an activity and contains further activities.
        // Plain querySelector() would hand a subsection the menu and the body
        // of its first child, which is why that child showed the marker items
        // twice and why picking one of them coloured the whole section.
        // -------------------------------------------------------------------

        var belongsTo = function(activityEl, node) {
            return node.closest('.activity[data-id]') === activityEl;
        };

        var findOwn = function(activityEl, selectors) {
            for (var i = 0; i < selectors.length; i++) {
                var candidates = activityEl.querySelectorAll(selectors[i]);
                for (var j = 0; j < candidates.length; j++) {
                    if (belongsTo(activityEl, candidates[j])) {
                        return candidates[j];
                    }
                }
            }
            return null;
        };

        /**
         * Whether this element holds other activities instead of being one.
         *
         * @param  {Element} activityEl
         * @return {boolean}
         */
        var isContainer = function(activityEl) {
            return activityEl.classList.contains('modtype_subsection') ||
                activityEl.querySelector('.activity[data-id]') !== null;
        };

        var applyModuleMarker = function(cmId, marker) {
            var moduleEl = findModuleElement(cmId);
            if (!moduleEl || isContainer(moduleEl)) {
                return;
            }
            var el = findOwn(moduleEl, ['.activity-item']) || moduleEl;
            MARKER_CLASSES.forEach(function(cls) { el.classList.remove(cls); });
            if (marker && MARKERS[marker]) {
                el.classList.add(MARKERS[marker].cssClass);
            }
        };

        var applyAllMarkers = function(markers) {
            Object.keys(markers).forEach(function(cmId) {
                if (markers[cmId]) {
                    applyModuleMarker(cmId, markers[cmId]);
                }
            });
        };

        // -----------------------------------------------------------------------
        // Build Bootstrap 5 dropdown elements
        // -----------------------------------------------------------------------

        var buildDivider = function() {
            var li = document.createElement('li');
            li.innerHTML = '<hr class="dropdown-divider sectionmarker-divider">';
            return li;
        };

        var buildItem = function(emoji, label, onClick) {
            var li = document.createElement('li');
            var a  = document.createElement('a');
            a.className   = 'dropdown-item sectionmarker-item';
            a.href        = '#';
            a.textContent = emoji + ' ' + label;
            a.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                onClick();
            });
            li.appendChild(a);
            return li;
        };

        // -----------------------------------------------------------------------
        // Find the dropdown <ul class="dropdown-menu"> inside an activity element
        // -----------------------------------------------------------------------

        var findDropdownMenu = function(activityEl) {
            return findOwn(activityEl, [
                '.activity-actions .dropdown-menu',
                '[data-region="action-menu"] .dropdown-menu',
                '[data-region="dropdown-menu-container"]',
                '.dropdown-menu'
            ]);
        };

        // -----------------------------------------------------------------------
        // Web service calls
        // -----------------------------------------------------------------------

        var handleMarkerClick = function(courseId, cmId, marker) {
            var calls;
            if (marker) {
                calls = Ajax.call([{
                    methodname: 'local_sectionmarker_set_marker',
                    args: {courseid: courseId, cmid: cmId, marker: marker}
                }]);
            } else {
                calls = Ajax.call([{
                    methodname: 'local_sectionmarker_remove_marker',
                    args: {courseid: courseId, cmid: cmId}
                }]);
            }
            calls[0].then(function() {
                applyModuleMarker(cmId, marker || null);
                return;
            }).catch(Notification.exception);
        };

        // -----------------------------------------------------------------------
        // Menu injection
        // -----------------------------------------------------------------------

        var injectItemsToActivity = function(courseId, activityEl, strings) {
            if (activityEl.hasAttribute(INJECTED_ATTR) || isContainer(activityEl)) {
                return;
            }

            var dropdownMenu = findDropdownMenu(activityEl);
            if (!dropdownMenu) {
                return;
            }

            // The cmid is the activity element's own data-id attribute.
            // In Moodle, <li id="module-42" data-id="42" class="activity ...">
            var cmId = parseInt(activityEl.dataset.id, 10);
            if (!cmId) {
                return;
            }

            activityEl.setAttribute(INJECTED_ATTR, '1');

            // The course editor re-renders activity cards, so the same menu can
            // be offered twice. One set of items per menu is enough.
            if (dropdownMenu.querySelector('.sectionmarker-item')) {
                return;
            }

            dropdownMenu.appendChild(buildDivider());

            var items = [
                {marker: 'info',    emoji: '\uD83D\uDD35', label: strings[0]},
                {marker: 'achtung', emoji: '\uD83D\uDFE1', label: strings[1]},
                {marker: 'ok',      emoji: '\uD83D\uDFE2', label: strings[2]},
                {marker: null,      emoji: '\u274C',        label: strings[3]}
            ];

            items.forEach(function(item) {
                var m = item.marker;
                dropdownMenu.appendChild(
                    buildItem(item.emoji, item.label, function() {
                        handleMarkerClick(courseId, cmId, m);
                    })
                );
            });
        };

        var injectAll = function(courseId, strings) {
            document.querySelectorAll('.activity[data-id]').forEach(function(activityEl) {
                injectItemsToActivity(courseId, activityEl, strings);
            });
        };

        // -----------------------------------------------------------------------
        // MutationObserver – handle activities added after page load
        // -----------------------------------------------------------------------

        var observeNewActivities = function(courseId, strings) {
            var root = document.querySelector('.course-content') || document.body;
            var observer = new MutationObserver(function(mutations) {
                mutations.forEach(function(mutation) {
                    mutation.addedNodes.forEach(function(node) {
                        if (node.nodeType !== Node.ELEMENT_NODE) {
                            return;
                        }
                        var candidates = [];
                        if (node.matches && node.matches('.activity[data-id]')) {
                            candidates.push(node);
                        }
                        if (node.querySelectorAll) {
                            node.querySelectorAll('.activity[data-id]').forEach(function(el) {
                                candidates.push(el);
                            });
                        }
                        candidates.forEach(function(el) {
                            injectItemsToActivity(courseId, el, strings);
                        });
                    });
                });
            });
            observer.observe(root, {childList: true, subtree: true});
        };

        // -----------------------------------------------------------------------
        // Observer for colour-only updates (always active, not just in edit mode)
        // -----------------------------------------------------------------------

        var observeColorUpdates = function(markers) {
            var root = document.querySelector('.course-content') || document.body;
            new MutationObserver(function(mutations) {
                mutations.forEach(function(mutation) {
                    mutation.addedNodes.forEach(function(node) {
                        if (node.nodeType !== Node.ELEMENT_NODE) {
                            return;
                        }
                        var candidates = [];
                        if (node.matches && node.matches('.activity[data-id]')) {
                            candidates.push(node);
                        }
                        if (node.querySelectorAll) {
                            node.querySelectorAll('.activity[data-id]').forEach(function(el) {
                                candidates.push(el);
                            });
                        }
                        candidates.forEach(function(el) {
                            var cmId = String(el.dataset.id);
                            if (markers[cmId]) {
                                applyModuleMarker(cmId, markers[cmId]);
                            }
                        });
                    });
                });
            }).observe(root, {childList: true, subtree: true});
        };

        // -----------------------------------------------------------------------
        // Public API
        // -----------------------------------------------------------------------

        var init = function(courseId, markers, isEditMode) {
            // Apply existing colours immediately (for all users).
            applyAllMarkers(markers);

            // Re-apply colours when activities are loaded dynamically (e.g. in view mode).
            observeColorUpdates(markers);

            // Only inject the edit-menu items for teachers/managers.
            if (!isEditMode) {
                return;
            }

            Str.get_strings([
                {key: 'mark_info',    component: 'local_sectionmarker'},
                {key: 'mark_achtung', component: 'local_sectionmarker'},
                {key: 'mark_ok',      component: 'local_sectionmarker'},
                {key: 'remove_mark',  component: 'local_sectionmarker'}
            ]).then(function(strings) {
                injectAll(courseId, strings);
                observeNewActivities(courseId, strings);
                return;
            }).catch(Notification.exception);
        };

        return {init: init};
    }
);
